/**
 * Public source registry: the only registry the website loads. It is
 * generated by scripts/registry/public.ts from data/registry/sources.json and
 * carries no internal analysis, rights evidence or excluded-source details.
 */
import registry from "../../../data/generated/sources.public.json";
import type { PrMetricId } from "./metrics";

export type PublicStatus = "PUBLIC_READY" | "PUBLIC_PENDING" | "PUBLIC_EXCLUDED";

/** A single stored value that is not shown, with the reason. */
export type ValueExclusion = { metric: string; municipioId: string; reason: "source_conflict" };

export type PublicSourceRecord = {
  datasetId: string;
  title: string;
  sourceAgency: string;
  sourceTitle: string;
  sourceURL: string | null;
  reportingPeriod: string;
  geography: "municipio" | "isla";
  attribution: string;
  methodology: string | null;
  missingValuePolicy: string;
  publicStatus: Exclude<PublicStatus, "PUBLIC_EXCLUDED">;
  verified: boolean;
  /** Date (UTC) the official snapshot was downloaded, when the project keeps one. */
  retrievedAt: string | null;
  marginOfErrorAvailable: boolean;
  metrics: string[];
  valueExclusions: ValueExclusion[];
};

export const PUBLIC_SOURCES = (registry as unknown as { records: PublicSourceRecord[] }).records;

const byMetric = new Map<string, PublicSourceRecord>();
for (const record of PUBLIC_SOURCES) {
  for (const metric of record.metrics) byMetric.set(metric, record);
}

/** Public record by datasetId (for sources with no metric, such as the map boundaries). */
export function publicSourceById(datasetId: string): PublicSourceRecord | null {
  return PUBLIC_SOURCES.find((record) => record.datasetId === datasetId) ?? null;
}

/** Null when the metric's source is excluded or unknown. */
export function publicSourceForMetric(id: PrMetricId): PublicSourceRecord | null {
  return byMetric.get(id) ?? null;
}

/**
 * Everything a "¿De dónde sale este dato?" view needs for one metric. The UI
 * reads this shape, so the registry can grow without touching components.
 */
export type MetricProvenance = {
  agency: string;
  title: string;
  period: string;
  geography: PublicSourceRecord["geography"];
  url: string | null;
  retrievedAt: string | null;
  methodology: string | null;
  missingValues: string;
  attribution: string;
  marginOfErrorAvailable: boolean;
  verified: boolean;
};

/** Registry text for people: an UNKNOWN marker reads as "Por confirmar". */
function forPeople(text: string): string {
  return text.replace(/^UNKNOWN\b\.?\s*/, "Por confirmar ").trim();
}

export function provenanceForMetric(id: PrMetricId): MetricProvenance | null {
  const record = publicSourceForMetric(id);
  if (!record) return null;
  return {
    agency: forPeople(record.sourceAgency),
    title: record.title,
    period: forPeople(record.reportingPeriod),
    geography: record.geography,
    url: record.sourceURL,
    retrievedAt: record.retrievedAt,
    methodology: record.methodology,
    missingValues: record.missingValuePolicy,
    attribution: record.attribution,
    marginOfErrorAvailable: record.marginOfErrorAvailable,
    verified: record.verified,
  };
}
